#include "search.h"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace retro {
static constexpr int Infinity=1000000,Mate=100000;static constexpr int Value[]={0,100,320,335,500,950,20000};
SearchConfig levelConfig(int l){switch(l){case 1:return {3,180};case 2:return {5,650};case 3:return {7,1600};case 4:return {9,3500};default:return {12,6500};}}
int Search::evaluate(const Chess& g)const{
 int mg=0,eg=0,phase=0,bishopCount[2]={0,0};int pawns[2][8]{};for(int s=0;s<128;++s){if(s&0x88){s+=7;continue;}int p=g.board[s],t=std::abs(p);if(!p)continue;int side=p>0?0:1;if(t==1)++pawns[side][s&7];if(t==3)++bishopCount[side];if(t==2||t==3)phase++;if(t==4)phase+=2;if(t==5)phase+=4;}
 for(int s=0;s<128;++s){if(s&0x88){s+=7;continue;}int p=g.board[s];if(!p)continue;int c=p>0?1:-1,side=c>0?0:1,t=std::abs(p),r=c>0?s>>4:7-(s>>4),f=s&7;int center=14-int(2*(std::abs(f-3.5)+std::abs((s>>4)-3.5)));int a=0,b=0;
 if(t==1){a=r*7+center*2;b=r*r*5+center;if(pawns[side][f]>1){a-=14;b-=20;}if((f==0||!pawns[side][f-1])&&(f==7||!pawns[side][f+1])){a-=15;b-=12;}bool passed=true;for(int ff=std::max(0,f-1);ff<=std::min(7,f+1);++ff)for(int rr=(s>>4)+c;rr>=0&&rr<8;rr+=c)if(g.board[rr*16+ff]==-c)passed=false;if(passed){a+=r*r*3;b+=r*r*10;}for(int d:{15,17}){int z=s-c*d;if(!(z&0x88)&&g.board[z]==c){a+=12;b+=8;}}}
 if(t==2){a=center*8-(r==0?18:0);b=center*6;}
 if(t==3){a=center*4+r*3;b=center*4;}
 if(t==4){a=(r==6?25:0);b=r*3;if(!pawns[side][f]){a+=14;if(!pawns[1-side][f])a+=12;}}
 if(t==5){a=center;b=center*3;}
 if(t>=2&&t<=5){std::vector<int> dirs=t==2?std::vector<int>{33,31,18,14,-14,-18,-31,-33}:t==3?std::vector<int>{15,-15,17,-17}:t==4?std::vector<int>{1,-1,16,-16}:std::vector<int>{1,-1,16,-16,15,-15,17,-17};int mobility=0;for(int d:dirs){int z=s+d;while(!(z&0x88)){if(g.board[z]*c>0)break;++mobility;if(g.board[z]||t==2)break;z+=d;}}int w=t==2?4:t==3?4:t==4?2:1;a+=mobility*w;b+=mobility*w;}
 if(t==6){a=-center*5-r*15;if(r==0&&(f==2||f==6))a+=32;for(int ff=std::max(0,f-1);ff<=std::min(7,f+1);ff++){int z=s+c*16+(ff-f);if(!(z&0x88)&&g.board[z]==c)a+=15;}b=center*10;}
 mg+=c*(Value[t]+a);eg+=c*(Value[t]+b);
 }
 for(int s=0;s<2;s++)if(bishopCount[s]>=2){mg+=(s==0?1:-1)*32;eg+=(s==0?1:-1)*45;}phase=std::min(24,phase);return ((mg*phase+eg*(24-phase))/24)*g.turn+12;
}
void Search::tick(){++nodes;if((nodes&1023)==0&&((cancelled&&cancelled->load())||std::chrono::steady_clock::now()>=deadline))throw std::runtime_error("stopped");}
uint64_t Search::push(){auto k=game.key();++repetition[k];return k;}void Search::pop(uint64_t k){--repetition[k];}
bool Search::drawn(){return game.half>=100||game.insufficient()||repetition[game.key()]>=3;}
uint64_t Search::ttKey(uint64_t k)const{return k^(uint64_t(game.half)*0x9e3779b97f4a7c15ULL);}
int Search::priority(Move m,Move tt,int ply)const{if(m==tt)return 2000000;int target=std::abs(game.board[m.to]);if(m.ep)target=1;int p=std::abs(game.board[m.from]);if(target)return 1000000+Value[target]*16-Value[p]+m.promotion*1000;if(m.promotion)return 900000+Value[m.promotion];if(ply<128){if(m==killers[ply][0])return 800000;if(m==killers[ply][1])return 790000;}return history[game.turn==1?0:1][m.from][m.to]+(m.castle?100:0);}
void Search::order(std::vector<Move>& moves,Move tt,int ply){std::stable_sort(moves.begin(),moves.end(),[&](auto a,auto b){return priority(a,tt,ply)>priority(b,tt,ply);});}
int Search::quiescence(int alpha,int beta,int ply,int left){tick();bool check=game.inCheck();auto moves=game.legal(!check);if(check&&moves.empty())return -Mate+ply;if(drawn())return 0;if(!check){if(moves.empty()&&game.legal().empty())return 0;int stand=evaluate(game);if(stand>=beta)return stand;alpha=std::max(alpha,stand);if(left<=0)return alpha;}else if(left<=-3||ply>=100)return evaluate(game);order(moves,{},ply);for(auto m:moves){Undo u=game.make(m);auto k=push();int score;try{score=-quiescence(-beta,-alpha,ply+1,left-1);}catch(...){pop(k);game.unmake(m,u);throw;}pop(k);game.unmake(m,u);if(score>=beta)return score;alpha=std::max(alpha,score);}return alpha;}
int Search::negamax(int depth,int alpha,int beta,int ply){tick();if(ply>=100)return evaluate(game);if(depth<=0)return quiescence(alpha,beta,ply,7);auto moves=game.legal();bool check=game.inCheck();if(moves.empty())return check?-Mate+ply:0;if(drawn())return 0;auto positionKey=game.key(),key=ttKey(positionKey);Entry& entry=table[key&(table.size()-1)];Move tt;bool cacheable=repetition[positionKey]<=1;int original=alpha;if(entry.key==key){tt=entry.move;if(cacheable&&entry.depth>=depth){int s=entry.score;if(s>Mate-1000)s-=ply;if(s<-Mate+1000)s+=ply;if(entry.bound==0||(entry.bound==1&&s>=beta)||(entry.bound==2&&s<=alpha))return s;}}
 order(moves,tt,ply);int best=-Infinity;Move bestMove;int number=0;for(auto m:moves){bool quiet=!game.board[m.to]&&!m.ep&&!m.promotion;Undo u=game.make(m);auto k=push();int score;try{int child=depth-1;if(number==0)score=-negamax(child,-beta,-alpha,ply+1);else{int reduction=depth>=4&&number>=4&&quiet&&!check&&!game.inCheck()?1:0;score=-negamax(child-reduction,-alpha-1,-alpha,ply+1);if(reduction&&score>alpha)score=-negamax(child,-alpha-1,-alpha,ply+1);if(score>alpha&&score<beta)score=-negamax(child,-beta,-alpha,ply+1);}}catch(...){pop(k);game.unmake(m,u);throw;}pop(k);game.unmake(m,u);++number;if(score>best){best=score;bestMove=m;}if(score>alpha)alpha=score;if(alpha>=beta){if(quiet){if(ply<128&&!(m==killers[ply][0])){killers[ply][1]=killers[ply][0];killers[ply][0]=m;}int& h=history[game.turn==1?0:1][m.from][m.to];h=std::min(700000,h+depth*depth*16);}break;}}
 if(cacheable&&(entry.key!=key||depth>=entry.depth)){int stored=best;if(stored>Mate-1000)stored+=ply;if(stored<-Mate+1000)stored-=ply;entry={key,bestMove,stored,depth,best>=beta?1:best<=original?2:0};}return best;}
SearchResult Search::bestMove(Chess position,SearchConfig config,const std::vector<uint64_t>& gameKeys,const std::shared_ptr<std::atomic_bool>& cancel){game=std::move(position);table.assign(1<<18,Entry{});repetition.clear();for(auto k:gameKeys)++repetition[k];if(!repetition[game.key()])++repetition[game.key()];cancelled=cancel;deadline=std::chrono::steady_clock::now()+std::chrono::milliseconds(config.milliseconds);nodes=0;SearchResult result;auto root=game.legal();if(root.empty())return result;result.move=root[0];for(int depth=1;depth<=config.depth;++depth){Move local;int score=-Infinity,alpha=-Infinity;order(root,result.move,0);try{for(auto m:root){if(cancelled&&cancelled->load())throw std::runtime_error("stopped");Undo u=game.make(m);auto k=push();int v;try{v=-negamax(depth-1,-Infinity,-alpha,1);}catch(...){pop(k);game.unmake(m,u);throw;}pop(k);game.unmake(m,u);if(v>score){score=v;local=m;}alpha=std::max(alpha,v);}}catch(const std::runtime_error&){break;}result.move=local;result.score=score;result.depth=depth;if(std::abs(score)>Mate-1000||std::chrono::steady_clock::now()>=deadline)break;}result.nodes=nodes;return result;}
}
